import{c as n,Q as a,j as i,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"ReasoningBank: Scaling Agent Self-Evolving with Reasoning Memory","description":"","frontmatter":{"url":"https://arxiv.org/abs/2509.25140","title":"ReasoningBank: Scaling Agent Self-Evolving with Reasoning Memory","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2509.2514,"authors":["Siru Ouyang","Jun Yan","I-Hung Hsu","Yanfei Chen","Ke Jiang"],"pdf_path":"pdfs/2509.25140.pdf","published_date":"2025-09-29T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-09-30-reasoningbank-scaling-agent-self-evolving-2509-25140.md","filePath":"research/papers/2025-09-30-reasoningbank-scaling-agent-self-evolving-2509-25140.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-09-30-reasoningbank-scaling-agent-self-evolving-2509-25140.md"};function r(o,e,l,g,c,m){return a(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>With the growing adoption of large language model agents in persistent real-world roles, they naturally encounter continuous streams of tasks. A key limitation, however, is their failure to learn from the accumulated interaction history, forcing them to discard valuable insights and repeat past errors. We propose ReasoningBank, a novel memory framework that distills generalizable reasoning strategies from an agent&#39;s self-judged successful and failed experiences. At test time, an agent retrieves relevant memories from ReasoningBank to inform its interaction and then integrates new learnings back, enabling it to become more capable over time. Building on this powerful experience learner, we further introduce memory-aware test-time scaling (MaTTS), which accelerates and diversifies this learning process by scaling up the agent&#39;s interaction experience. By allocating more compute to each task, the agent generates abundant, diverse experiences that provide rich contrastive signals for synthesizing higher-quality memory. The better memory in turn guides more effective scaling, establishing a powerful synergy between memory and test-time scaling. Across web browsing and software engineering benchmarks, ReasoningBank consistently outperforms existing memory mechanisms that store raw trajectories or only successful task routines, improving both effectiveness and efficiency; MaTTS further amplifies these gains. These findings establish memory-driven experience scaling as a new scaling dimension, enabling agents to self-evolve with emergent behaviors naturally arising.</p><h2 id="主要貢獻" tabindex="-1">主要貢獻 <a class="header-anchor" href="#主要貢獻" aria-label="Permalink to &quot;主要貢獻&quot;">​</a></h2><ul><li><strong>ReasoningBank 記憶框架</strong>：從 agent 自我評判的成功與失敗經驗中，蒸餾出可泛化的推理策略（reasoning strategies），而非儲存原始軌跡或只儲存成功例子。</li><li><strong>自我進化循環</strong>：agent 在測試時從 ReasoningBank 檢索相關記憶以指導當前任務，完成後將新學習整合回記憶庫，實現持續能力提升。</li><li><strong>MaTTS（Memory-aware Test-Time Scaling）</strong>：透過為每個任務分配更多算力，讓 agent 生成豐富、多元的互動經驗，提供更強的對比信號以合成更高品質記憶；更好的記憶反過來引導更有效的 scaling，形成正向循環。</li><li><strong>雙向對比學習</strong>：同時利用成功與失敗的自我評判經驗作為對比信號，優於只儲存成功例子的方法。</li><li><strong>實驗結果</strong>：在 web browsing 和 software engineering benchmark 上，ReasoningBank 在效果與效率上均優於儲存原始軌跡或只儲存成功例子的記憶機制；MaTTS 進一步放大收益。</li><li><strong>記憶驅動的經驗 scaling</strong>：確立了以記憶驅動的經驗 scaling 作為新的 scaling 維度，使 agent 能夠自我進化並展現湧現行為。</li></ul><h2 id="論文全文" tabindex="-1">論文全文 <a class="header-anchor" href="#論文全文" aria-label="Permalink to &quot;論文全文&quot;">​</a></h2><blockquote><p>HTML 全文暫不可用（arxiv HTML 轉換尚未完成）。以下為摘要頁面完整資訊。</p></blockquote><p><strong>Title</strong>: ReasoningBank: Scaling Agent Self-Evolving with Reasoning Memory <strong>Authors</strong>: Siru Ouyang, Jun Yan, I-Hung Hsu, Yanfei Chen, Ke Jiang <strong>arXiv ID</strong>: 2509.25140 <strong>Published</strong>: 2025-09-29 <strong>URL</strong>: <a href="https://arxiv.org/abs/2509.25140" target="_blank" rel="noreferrer">https://arxiv.org/abs/2509.25140</a></p><h3 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h3><p>With the growing adoption of large language model agents in persistent real-world roles, they naturally encounter continuous streams of tasks. A key limitation, however, is their failure to learn from the accumulated interaction history, forcing them to discard valuable insights and repeat past errors. We propose ReasoningBank, a novel memory framework that distills generalizable reasoning strategies from an agent&#39;s self-judged successful and failed experiences. At test time, an agent retrieves relevant memories from ReasoningBank to inform its interaction and then integrates new learnings back, enabling it to become more capable over time. Building on this powerful experience learner, we further introduce memory-aware test-time scaling (MaTTS), which accelerates and diversifies this learning process by scaling up the agent&#39;s interaction experience. By allocating more compute to each task, the agent generates abundant, diverse experiences that provide rich contrastive signals for synthesizing higher-quality memory. The better memory in turn guides more effective scaling, establishing a powerful synergy between memory and test-time scaling. Across web browsing and software engineering benchmarks, ReasoningBank consistently outperforms existing memory mechanisms that store raw trajectories or only successful task routines, improving both effectiveness and efficiency; MaTTS further amplifies these gains. These findings establish memory-driven experience scaling as a new scaling dimension, enabling agents to self-evolve with emergent behaviors naturally arise.</p><h3 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h3><p><strong>ReasoningBank vs. prior memory approaches</strong>:</p><ul><li>Raw trajectory storage: Stores full interaction history → context bloat, noise</li><li>Success-only memory (e.g., EXPEL, Voyager): Misses failure lessons, incomplete signal</li><li>ReasoningBank: Distills strategies from both successes and failures via self-judgment → higher-quality, generalizable memory</li></ul><p><strong>Memory-aware Test-Time Scaling (MaTTS)</strong>:</p><ul><li>Allocates more compute per task to generate diverse interaction experiences</li><li>These diverse experiences provide richer contrastive signals for memory synthesis</li><li>Improved memory quality feeds back into better scaling effectiveness</li><li>Establishes a synergy loop: better memory → better scaling → better memory</li></ul><p><strong>Self-evolution mechanism</strong>:</p><ol><li>Agent receives task, retrieves relevant memories from ReasoningBank</li><li>Agent attempts task, generating multiple experiences (with MaTTS: more diverse attempts)</li><li>Agent self-judges which experiences were successful vs. failed</li><li>System distills generalizable reasoning strategies from the contrastive signal</li><li>New strategies are integrated back into ReasoningBank</li><li>Repeat → agent capability improves over time</li></ol><p><strong>Benchmarks</strong>: Web browsing tasks + software engineering tasks (likely WebArena, SWE-bench or similar)</p><p><strong>Core claim</strong>: Memory-driven experience scaling is a new scaling dimension distinct from model size scaling or inference compute scaling, enabling genuine agent self-evolution.</p>',18)])])}const p=n(s,[["render",r]]);export{u as __pageData,p as default};
